      + `${button('create-alert', two('Create alert', 'Alert'), 'quiet', 'aria-label="Create alert"')}`
      + (canExport() ? `${button('export-open', `Export…<span class="ew-short ew-export-n">${selectedCount ? ` (${selectedCount})` : ''}</span>`, 'quiet', `aria-haspopup="dialog"${nothingToExport ? `${planLimited ? ' aria-describedby="plan-limited-why"' : ' aria-describedby="export-open-why"'} disabled` : ''}`)}`
      + (nothingToExport && !planLimited ? `<span class="ew-help" id="export-open-why">Nothing to export: this search found no results.</span>` : '') : '') + `</div>`
