    const { signal, live } = guardedFetch(token);
    // The rail reads its filter values with the page (1200 px and up only).
    const wide = !!(window.matchMedia && window.matchMedia('(min-width: 1200px)').matches);
    const refresh = E.current.cohortRefresh === true;
    E.current.cohortRefresh = false;
    // D-6: All mentions with no words and no brand is a prompt, not the
    // whole transcript list: no research request. A chart selection or an
