        + `<h2>${invalid ? 'This scope was not applied' : 'We couldn’t complete this search'}</h2>`
        + `<p>${esc((invalid ? 'This scope is invalid and was not applied: ' : 'Search is unavailable: ') + cohortError)}</p>`
        + `<p>This is not “no results”. Your search and filters are kept.</p>`
        + `<div class="actions">${button('retry', 'Retry', 'primary')}${button('reset-filters', 'Reset scope', 'quiet')}</div></div>`;
      const failure = `${h1}${searchHead(c, { chips: chipCount })}${failureCard}`;
