    // Row 1: Ads counts ads; an older server's Ads (no ad count) shows no number.
    const totalText = adBreaks ? adCount(breakTotal, relation) : mode === 'ads' ? '' : `${relation}${E.num(total)} ${countNoun(mode, total)}`;
    const countLine = !items.length ? `No ${searchNoun(mode, 2)} found`
      : totalText ? `Showing ${E.num(first)} to ${E.num(last)} of ${totalText}` : 'Ads found · count not available';
    const viewSwitch = mode === 'ads'
      ? `<fieldset class="ew-segmented ew-view-switch"><legend class="visually-hidden">View</legend><div class="ew-segmented-options">`
        + `<label><input type="radio" name="results_view" value="cards"${view === 'cards' ? ' checked' : ''}>Cards</label>`
        + `<label><input type="radio" name="results_view" value="list"${view === 'list' ? ' checked' : ''}>List</label></div></fieldset>` : '';
    // Plan A: mentions is not offered (no button); a plan-limited answer
