      + (mode === 'ads' && query.q && !excerptOnly() ? link(E.searchURL({ mode: 'mentions', q: query.q, page: 1 }), 'Search all mentions', 'button quiet') : '')
      + button('create-alert', mode === 'ads' ? 'Create an alert for new ads' : 'Create an alert', 'quiet');
    const emptyTitle = query.q ? `No ${searchNoun(mode, 2)} say “${query.q}” in this scope` : `No ${searchNoun(mode, 2)} in this scope`;
    const emptyBody = mode === 'ads'
