      const where = [s.show_title, s.ep_title, s.pub_date ? E.date(s.pub_date) : ''].filter(Boolean).map(esc).join(' · ');
      return `<li class="ew-work-event-group"><div class="ew-work-group-head"><span class="ew-work-group-where">${where}</span> · ${esc(E.plural(changeCount(g.events), 'change'))}${found ? ` · Found ${E.stamp(found)}` : ''}</div>`
