    const { unchecked, latest, current, earlier } = split;
    const latestElsewhere = !unchecked && !latest.length && whole.latest.length > 0;
    const ep = alert.event_page || {};
    const latestPages = Array.isArray(ep.latest_check_pages) ? ep.latest_check_pages.filter(Number.isInteger) : [];
    const pointer = latestElsewhere && pageHref && latestPages.length && latestPages[0] !== ep.page
      ? `<p class="section-note ew-work-import">This check’s matches ${latestPages.length === 1 ? 'are' : 'start'} on ${link(pageHref(latestPages[0]), 'page ' + latestPages[0])}.</p>` : '';
    const list = (evs, terms) => { const r = alertEventsHtml(evs, terms); return r.note + `<ul class="ew-card-list ew-work-events">${r.html}</ul>`; };
    const sub = t => `<h3 class="ew-alert-subhead">${t}</h3>`;
    // VL-14: the last check ran under earlier settings, so it is not
