  const SEARCH_UNITS = { mentions: ['passage', 'passages'], ads: ['ad', 'ads'], episodes: ['episode', 'episodes'] };
  const unitText = (units, n) => (n === 1 ? units[0] : units[1]);
  // One total per card: what the alert tracks (passages and ads, held
