      + (alert.lifecycle !== 'stopped' && mayChange ? button('pause-alert', alert.lifecycle === 'paused' ? 'Resume' : 'Pause', '', `data-id="${alert.id}" data-rev="${alert.revision}" data-lifecycle="${alert.lifecycle}"`) + button('stop-alert', 'Stop alert', 'quiet', `data-id="${alert.id}" data-rev="${alert.revision}"`) : '')
