      if (form.querySelector('[name=brand]')) patch.brands = v.brand ? [v.brand] : null;
      if (form.querySelector('[name=from]') || form.querySelector('[name=to]')) {
        if (v.from && v.to && v.to < v.from) return E.formError('The end date must be on or after the start date.', form.querySelector('[name=to]'), form);
        if ((v.from && !/^\d{4}-\d{2}-\d{2}$/.test(v.from)) || (v.to && !/^\d{4}-\d{2}-\d{2}$/.test(v.to))) return E.formError('Enter real calendar dates.', form.querySelector('[name=from]'), form);
        patch.from = v.from || null;
        patch.to = v.to || null;
      }
