      out += (rest.length === 1 ? `<p class="ask-line">${esc(rest[0])}</p>` : rest.length ? `<ul class="ask-lines">${rest.map(l => `<li>${esc(l)}</li>`).join('')}</ul>` : '')
        + (read && sources.length ? '<p class="ask-line">Passages about this, to read for yourself:</p>' : '')
        + `<section class="ask-sources"><h3>Sources · ${sources.length} passage${sources.length === 1 ? '' : 's'}</h3><ol>${sources.map((s, i) => askSourceHtml(turn, s, i + 1)).join('')}</ol></section>`
