      // workspace or person); leaving #/ask only skips the drawing.
      if (ask.gen !== gen) return;
      // A prepared send shows the brand button's own words until the first read brings the stored question.
      const question = body.question || 'What podcasts say about ' + String(body.prepared || '').replace(/^brand:/, '');
      const turn = { turn_id: out.turn_id, thread_id: out.thread_id, question, state: 'working', step: 1 };
      if (replace) { ask.turns = []; ask.sent.clear(); }
      ask.sent.set(turn.turn_id, body);
      ask.threadId = out.thread_id;
